CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INT COLLATE NOCASE, c1 NUMERIC COLLATE NOCASE, c2 INT, c3 REAL CHECK(c3 IS NULL OR length(c3) < 40), c4 INTEGER UNIQUE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('日本', 1e308, -8, 'señor', 'alpha');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(NULL, -3, -1, 'epsilon', 760);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT CHECK(c0 IS NULL OR length(c0) < 40), c1 TEXT, c2 REAL, c3 VARCHAR(10), c4 NUMERIC CHECK(c4 IS NULL OR length(c4) < 40), ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(NULL, 'señor', -719.4, x'1ada', 3, NULL);
