INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(2.5, x'2eb3ad4bba', 'Ελλάδα', NULL, 9223372036854775807, 7);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(500, 'gamma', 4.5e-310, x'4d374031ed15', 339, NULL);
