CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 INT UNIQUE, c1 NUMERIC, c2 TEXT UNIQUE, c3 TEXT, c4 VARCHAR(10) CHECK(c4 IS NULL OR length(c4) < 40));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, c4) VALUES(NULL, -455, 'eta', NULL, -3);
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, c4) VALUES(1e-7, -44, NULL, NULL, -2.5);
