SELECT length('日本'), upper('日本'), lower('日本'), substr('日本', -1, 2), instr('日本', '42'), replace('日本', '', '_'), trim('日本'), ltrim('日本', 'ab'), hex('日本'), quote('日本'), unicode('日本'), '日本' LIKE '_', '日本' GLOB 'a*', char(82, 242), '日本' || '42', '日本' < '42', '日本' = '42' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 0, 2), instr('pi', 'a%b'), replace('pi', 'é', 'XY'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE 'A%', 'pi' GLOB 'a*', char(89, 623), 'pi' || 'a%b', 'pi' < 'a%b', 'pi' = 'a%b' COLLATE NOCASE;
SELECT length('MU'), upper('MU'), lower('MU'), substr('MU', -3, 5), instr('MU', '日本'), replace('MU', 'a', 'XY'), trim('MU'), ltrim('MU', 'ab'), hex('MU'), quote('MU'), unicode('MU'), 'MU' LIKE 'a%', 'MU' GLOB 'a*', char(74, 973), 'MU' || '日本', 'MU' < '日本', 'MU' = '日本' COLLATE NOCASE;
SELECT length('zeta'), upper('zeta'), lower('zeta'), substr('zeta', 1, 2), instr('zeta', 'Ελλάδα'), replace('zeta', 'a', ''), trim('zeta'), ltrim('zeta', 'ab'), hex('zeta'), quote('zeta'), unicode('zeta'), 'zeta' LIKE 'a%', 'zeta' GLOB '*', char(71, 438), 'zeta' || 'Ελλάδα', 'zeta' < 'Ελλάδα', 'zeta' = 'Ελλάδα' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', 1, 5), instr('sigma', 'MU'), replace('sigma', 'a', '_'), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE '%é%', 'sigma' GLOB '*[a-m]*', char(84, 306), 'sigma' || 'MU', 'sigma' < 'MU', 'sigma' = 'MU' COLLATE NOCASE;
SELECT length('tau'), upper('tau'), lower('tau'), substr('tau', -1, 4), instr('tau', 'MU'), replace('tau', 'é', ''), trim('tau'), ltrim('tau', 'ab'), hex('tau'), quote('tau'), unicode('tau'), 'tau' LIKE '%', 'tau' GLOB '?', char(90, 247), 'tau' || 'MU', 'tau' < 'MU', 'tau' = 'MU' COLLATE NOCASE;
SELECT id, nullif(c0, -5) IS NULL, 'tau' FROM t0 ORDER BY id, c0, c1, c2, c3, c4 DESC;
SELECT (((-990 IS NOT 'Lambda') OR abs(x'530c5269d1')) <> nullif(-769.856 BETWEEN NULL AND 'zeta', nullif(NULL, -326))), NOT NULL IN (x'f648809f', NULL, x'cf7e');
UPDATE t1 SET c0 = iif(ref, -288.814 IN (453, -144, 'xi'), -1) WHERE c1;
DELETE FROM t1 WHERE id % 5 = 0;
SELECT * FROM t1 ORDER BY id DESC, c0 DESC, c1, c2, c3, c4, ref;
